function canShareParity(nums: number[]): boolean {
  const n = nums.length;
  for (const target of [0, 1]) {
    let ok = true;
    for (let i = 0; i < n && ok; i++) {
      if ((nums[i] & 1) === target) continue;
      let reach = false;
      for (let j = 0; j < n && !reach; j++) {
        if (j !== i && ((nums[i] - nums[j]) & 1) === target) reach = true;
      }
      if (!reach) ok = false;
    }
    if (ok) return true;
  }
  return false;
}

