class Solution:
    def canShareParity(self, nums: List[int]) -> bool:
        n = len(nums)
        for target in (0, 1):
            if all(
                nums[i] % 2 == target
                or any(j != i and (nums[i] - nums[j]) % 2 == target for j in range(n))
                for i in range(n)
            ):
                return True
        return False

